window.__votdWeek && window.__votdWeek({"week":"2029-08-20","reading":"Doctrine and Covenants 89–92","days":[{"d":"2029-08-20","ref":"D&C 89:18","b":"D&C","c":89,"v":18,"he":"וְכׇל הַקְּדוֹשִׁים אֲשֶׁר יִזְכְּרוּ לִשְׁמֹר וְלַעֲשׂוֹת אֶת־הַדְּבָרִים הָאֵלֶּה הֹלְכִים וְשֹׁמְעִים לַמִּצְווֹת יְקַבְּלוּ רִפְאוּת לְשָׁרָּם וְשִׁקּוּי לְעַצְמוֹתֵיהֶם׃","en":"And all saints who remember to keep and do these sayings, walking in obedience to the commandments, shall receive health in their navel and marrow to their bones;"},{"d":"2029-08-21","ref":"D&C 89:20","b":"D&C","c":89,"v":20,"he":"וְיָרוּצוּ וְלֹא יִיגָעוּ וְיֵלְכוּ וְלֹא יִיעָפוּ׃","en":"And shall run and not be weary, and shall walk and not faint."},{"d":"2029-08-22","ref":"D&C 89:21","b":"D&C","c":89,"v":21,"he":"וַאֲנִי יְהוָה נוֹתֵן לָהֶם הַבְטָחָה כִּי הַמַּשְׁחִית יִפְסַח עֲלֵיהֶם כִּבְנֵי יִשְׂרָאֵל וְלֹא יַכֵּם אָמֵן׃","en":"And I, the Lord, give unto them a promise, that the destroying angel shall pass by them, as the children of Israel, and not slay them. Amen."},{"d":"2029-08-23","ref":"D&C 90:10","b":"D&C","c":90,"v":10,"he":"וְאָז יָבוֹא הַיּוֹם אֲשֶׁר תִּגָּלֶה זְרוֹעַ יְהוָה בְּכֹחַ לְהוֹכִיחַ הַגּוֹיִם גּוֹיֵי הַנֵּכָר בֵּית יוֹסֵף אֶת־בְּשׂוֹרַת יְשׁוּעָתָם׃","en":"And then cometh the day when the arm of the Lord shall be revealed in power in convincing the nations, the heathen nations, the house of Joseph, of the gospel of their salvation."},{"d":"2029-08-24","ref":"D&C 90:24","b":"D&C","c":90,"v":24,"he":"דִּרְשׁוּ הֵיטֵב הִתְפַּלְּלוּ תָמִיד וְהַאֲמִינוּ וְכׇל־דָּבָר יֵעָשֶׂה לְטוֹבַתְכֶם אִם תֵּלְכוּ בְּיֹשֶׁר וְתִזְכְּרוּ אֶת־הַבְּרִית אֲשֶׁר כְּרַתֶּם אִישׁ עִם אָחִיו׃","en":"Search diligently, pray always, and be believing, and all things shall work together for your good, if ye walk uprightly and remember the covenant wherewith ye have covenanted one with another."},{"d":"2029-08-25","ref":"D&C 91:3","b":"D&C","c":91,"v":3,"he":"אָמֵן אֲנִי אֹמֵר לָכֶם כִּי אֵין נָכוֹן אֲשֶׁר יְתֻרְגְּמוּ הַסְּפָרִים הַחִיצוֹנִים׃","en":"Verily, I say unto you, that it is not needful that the Apocrypha should be translated."},{"d":"2029-08-26","ref":"D&C 92:1","b":"D&C","c":92,"v":1,"he":"אָמֵן כֹּה אָמַר יְהוָה אֲנִי נֹתֵן לַסֵּדֶר הַמְאֻחָד הַמְיֻסָּד כַּמִּצְוָה אֲשֶׁר־נִתְּנָה לְפָנִים חָזוֹן וּמִצְוָה עַל־אֹדוֹת עַבְדִּי פְרֶדֶרִיק ג׳. וִילְיָמְס כִּי תְּקַבְּלוּהוּ אֶל־הַסֵּדֶר אֲשֶׁר אֲנִי אֹמֵר לְאֶחָד אֲנִי אֹמֵר לַכֹּל׃","en":"Verily, thus saith the Lord, I give unto the united order, organized agreeable to the commandment previously given, a revelation and commandment concerning my servant Frederick G. Williams, that ye shall receive him into the order. What I say unto one I say unto all."}]});
